def f(n):
    """ Create the function f to handle a single parameter n.
    It returns a list with n elements where each value at index i is the factorial of i if even,
    or the cumulative sum from 1 to i if odd. Index i starts at 1.
    Example:
    f(5) == [1, 2, 6, 24, 15]
    """
    def factorial(num):
        if num == 0:
            return 1
        else:
            return num * factorial(num - 1)

    result = []
    for i in range(1, n+1):
        if i % 2 == 0:
            result.append(factorial(i))
        else:
            result.append(sum(range(1, i+1))

    return result
