def bf(planet1, planet2):
    planets = ["Mercury", "Venus", "Earth", "Mars", "Jupiter", "Saturn", "Uranus", "Neptune"]

    if planet1 not in planets or planet2 not in planets:
        return ()

    planet_order = {planet: index for index, planet in enumerate(planets)}

    start = min(planet_order[planet1], planet_order[planet2])
    end = max(planet_order[planet1], planet_order[planet2])

    result = [planet for planet in planets if start < planet_order[planet] < end]

    return tuple(sorted(result, key=lambda x: planet_order[x]))

